typedef enum MD_SPANTYPE {
    /* <em>...</em> */
    MD_SPAN_EM,

    /* <strong>...</strong> */
    MD_SPAN_STRONG,

    /* <a href="xxx">...</a>
     * Detail: Structure MD_SPAN_A_DETAIL. */
    MD_SPAN_A,

    /* <img src="xxx">...</a>
     * Detail: Structure MD_SPAN_IMG_DETAIL.
     * Note: Image text can contain nested spans and even nested images.
     * If rendered into ALT attribute of HTML <IMG> tag, it's responsibility
     * of the parser to deal with it.
     */
    MD_SPAN_IMG,

    /* <code>...</code> */
    MD_SPAN_CODE,

    /* <del>...</del>
     * Note: Recognized only when MD_FLAG_STRIKETHROUGH is enabled.
     */
    MD_SPAN_DEL,

    /* For recognizing inline ($) and display ($$) equations
     * Note: Recognized only when MD_FLAG_LATEXMATHSPANS is enabled.
     */
    MD_SPAN_LATEXMATH,
    MD_SPAN_LATEXMATH_DISPLAY,

    /* Wiki links
     * Note: Recognized only when MD_FLAG_WIKILINKS is enabled.
     */
    MD_SPAN_WIKILINK,

    /* <u>...</u>
     * Note: Recognized only when MD_FLAG_UNDERLINE is enabled. */
    MD_SPAN_U
} MD_SPANTYPE;

/* A potential table cell boundary or wiki link label delimiter. */
if((table_mode || ctx->parser.flags & MD_FLAG_WIKILINKS) && ch == _T('|')) {
    ADD_MARK(ch, off, off+1, 0);
    off++;
    continue;
}

    /* Spoiler (hidden content revealed on interaction).
     * Syntax: ||hidden text||
     * Note: Recognized only when MD_FLAG_SPOILERS is enabled. */
    MD_SPAN_SPOILER
} MD_SPANTYPE;

MD_PARSER parser = {
    0,
    parser_flags,
    enter_block_callback,
    leave_block_callback,
    enter_span_callback,
    leave_span_callback,
    text_callback,
    debug_log_callback,
    NULL
};

/* Build map of characters which need escaping. */
for(i = 0; i < 256; i++) {
    unsigned char ch = (unsigned char) i;

    if(strchr("\"&<>", ch) != NULL)
        render.escape_map[i] |= NEED_HTML_ESC_FLAG;

    if(!ISALNUM(ch)  &&  strchr("~-_.+!*(),%#@?=;:/,+$", ch) == NULL)
        render.escape_map[i] |= NEED_URL_ESC_FLAG;
}

/* Consider skipping UTF-8 byte order mark (BOM). */
if(renderer_flags & MD_HTML_FLAG_SKIP_UTF8_BOM  &&  sizeof(MD_CHAR) == 1) {
    static const MD_CHAR bom[3] = { (char)0xef, (char)0xbb, (char)0xbf };
    if(input_size >= sizeof(bom)  &&  memcmp(input, bom, sizeof(bom)) == 0) {
        input += sizeof(bom);
        input_size -= sizeof(bom);
    }
}

return md_parse(input, input_size, &parser, (void*) &render);

switch(block->type) {
    case MD_BLOCK_HR:
        /* noop */
        break;

    case MD_BLOCK_CODE:
        MD_CHECK(md_process_code_block_contents(ctx, (block->data != 0),
                        (const MD_VERBATIMLINE*)(block + 1), block->n_lines));
        break;

    case MD_BLOCK_HTML:
        MD_CHECK(md_process_verbatim_block_contents(ctx, MD_TEXT_HTML,
                        (const MD_VERBATIMLINE*)(block + 1), block->n_lines));
        break;

    case MD_BLOCK_TABLE:
        MD_CHECK(md_process_table_block_contents(ctx, block->data,
                        (const MD_LINE*)(block + 1), block->n_lines));
        break;

    default:
        MD_CHECK(md_process_normal_block_contents(ctx,
                        (const MD_LINE*)(block + 1), block->n_lines));
        break;

static int
md_process_normal_block_contents(MD_CTX* ctx, const MD_LINE* lines, MD_SIZE n_lines)
{
    int i;
    int ret;

    MD_CHECK(md_analyze_inlines(ctx, lines, n_lines, FALSE));
    MD_CHECK(md_process_inlines(ctx, lines, n_lines));

/* A potential spoiler delimiter: || ... ||
 * Checked before the single-| handler so a double pipe is consumed
 * as one mark and does not become two cell boundaries. */
if(ch == _T('|') && (ctx->parser.flags & MD_FLAG_SPOILERS)) {
    if(off + 1 < line->end && CH(off+1) == _T('|')) {
        ADD_MARK(ch, off, off+2, MD_MARK_POTENTIAL_OPENER | MD_MARK_POTENTIAL_CLOSER);
        off += 2;
        continue;
    }
}

if(ctx->parser.flags & MD_FLAG_SPOILERS) {
    for(i = mark_beg; i < mark_end; i++) {
        MD_MARK* mark = &ctx->marks[i];
        if(mark->flags & MD_MARK_RESOLVED)
            continue;
        if(mark->ch == '|' && mark->end - mark->beg == 2)
            md_analyze_pipe(ctx, i);
    }
}

static void
md_analyze_pipe(MD_CTX* ctx, int mark_index)
{
    MD_MARK* mark = &ctx->marks[mark_index];

    if((mark->flags & MD_MARK_POTENTIAL_CLOSER)  &&  PIPE_OPENERS.top >= 0) {
        int opener_index = PIPE_OPENERS.top;

        md_pop_openers(ctx, opener_index);
        md_resolve_range(ctx, opener_index, mark_index);
        return;
    }

    if(mark->flags & MD_MARK_POTENTIAL_OPENER)
        md_mark_stack_push(ctx, &PIPE_OPENERS, mark_index);
}

case '|':
    if(mark->end - mark->beg == 2) {
        if(mark->flags & MD_MARK_OPENER)
            MD_ENTER_SPAN(MD_SPAN_SPOILER, NULL);
        else
            MD_LEAVE_SPAN(MD_SPAN_SPOILER, NULL);
    }
    break;

case MD_SPAN_CODE:              RENDER_VERBATIM(r, "<code>"); break;
case MD_SPAN_DEL:               RENDER_VERBATIM(r, "<del>"); break;
case MD_SPAN_SPOILER:           RENDER_VERBATIM(r, "<x-spoiler>"); break;
case MD_SPAN_LATEXMATH:         RENDER_VERBATIM(r, "<x-equation>"); break;

case MD_SPAN_IMG:               render_close_img_span(r, (MD_SPAN_IMG_DETAIL*) detail); break;
case MD_SPAN_CODE:              RENDER_VERBATIM(r, "</code>"); break;
case MD_SPAN_DEL:               RENDER_VERBATIM(r, "</del>"); break;
case MD_SPAN_SPOILER:           RENDER_VERBATIM(r, "</x-spoiler>"); break;
case MD_SPAN_LATEXMATH:         /*fall through*/
case MD_SPAN_LATEXMATH_DISPLAY: RENDER_VERBATIM(r, "</x-equation>"); break;
